import java.util.*;

public class Main {
    public static void main(String[] args) {
        MessageQueue queue = new MessageQueue();

        // A producer publishes 3 messages to partition 0.
        queue.publish(0, "order-created");
        queue.publish(0, "order-paid");
        queue.publish(0, "order-shipped");

        // Consumer group "analytics" polls and reads all 3 messages, advancing its own offset to 3.
        System.out.println("analytics poll 1: " + queue.poll("analytics", 0, 10));

        // Consumer group "notifications" is entirely independent: it has never read partition 0 before,
        // so it also starts from offset 0 and reads the exact same 3 messages, unaffected by "analytics".
        System.out.println("notifications poll 1: " + queue.poll("notifications", 0, 10));

        // A 4th message is published.
        queue.publish(0, "order-delivered");

        // "analytics" only gets the new message, since its own offset was already at 3.
        System.out.println("analytics poll 2 (only new messages): " + queue.poll("analytics", 0, 10));

        // "notifications" also only gets the new message, since its own offset was independently at 3 too.
        System.out.println("notifications poll 2 (only new messages): " + queue.poll("notifications", 0, 10));

        // The log itself still holds all 4 messages, retained regardless of either group's consumption.
        System.out.println("Partition 0 still retains all published messages: " + queue.partitionSize(0));
    }
}

// A partitioned, append-only, retained message log with independent
// per-consumer-group offset tracking, the core Kafka-style pub/sub model:
// reading a message never removes it, and different groups can be at
// completely different positions in the same log at the same time.
class MessageQueue {
    private final Map<Integer, List<String>> partitions = new HashMap<>(); // partitionId -> retained, ordered messages
    private final Map<String, Map<Integer, Integer>> offsetsByGroup = new HashMap<>(); // groupId -> (partitionId -> next offset to read)

    void publish(int partitionId, String payload) {
        partitions.computeIfAbsent(partitionId, id -> new ArrayList<>()).add(payload); // appended, never removed on read
    }

    // Reads up to maxMessages new messages for this group from its own,
    // independently tracked offset, and advances that group's offset.
    List<String> poll(String groupId, int partitionId, int maxMessages) {
        List<String> log = partitions.getOrDefault(partitionId, Collections.emptyList());
        Map<Integer, Integer> groupOffsets = offsetsByGroup.computeIfAbsent(groupId, id -> new HashMap<>());
        int currentOffset = groupOffsets.getOrDefault(partitionId, 0); // this group's own position, independent of any other group

        List<String> result = new ArrayList<>();
        int end = Math.min(log.size(), currentOffset + maxMessages);
        for (int i = currentOffset; i < end; i++) {
            result.add(log.get(i));
        }

        groupOffsets.put(partitionId, end); // advance only this group's own offset
        return result;
    }

    int partitionSize(int partitionId) {
        return partitions.getOrDefault(partitionId, Collections.emptyList()).size();
    }
}

