#include <iostream>
#include <map>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

// A partitioned, append-only, retained message log with independent
// per-consumer-group offset tracking, the core Kafka-style pub/sub model:
// reading a message never removes it, and different groups can be at
// completely different positions in the same log at the same time.
class MessageQueue {
public:
    void publish(int partitionId, const string& payload) {
        partitions[partitionId].push_back(payload); // appended, never removed on read
    }

    vector<string> poll(const string& groupId, int partitionId, int maxMessages) {
        vector<string>& log = partitions[partitionId];
        map<int, int>& groupOffsets = offsetsByGroup[groupId];
        int currentOffset = groupOffsets.count(partitionId) ? groupOffsets[partitionId] : 0; // this group's own position

        int end = min((int)log.size(), currentOffset + maxMessages);
        vector<string> result(log.begin() + currentOffset, log.begin() + end);

        groupOffsets[partitionId] = end; // advance only this group's own offset
        return result;
    }

    int partitionSize(int partitionId) {
        return partitions[partitionId].size();
    }

private:
    map<int, vector<string>> partitions;                 // partitionId -> retained, ordered messages
    map<string, map<int, int>> offsetsByGroup;              // groupId -> (partitionId -> next offset to read)
};

void printVector(const string& label, const vector<string>& v) {
    cout << label << ": [";
    for (size_t i = 0; i < v.size(); i++) {
        cout << v[i];
        if (i + 1 < v.size()) cout << ", ";
    }
    cout << "]" << endl;
}

int main() {
    MessageQueue queue;

    // A producer publishes 3 messages to partition 0.
    queue.publish(0, "order-created");
    queue.publish(0, "order-paid");
    queue.publish(0, "order-shipped");

    // Consumer group "analytics" polls and reads all 3 messages, advancing its own offset to 3.
    printVector("analytics poll 1", queue.poll("analytics", 0, 10));

    // Consumer group "notifications" is entirely independent: it has never read partition 0 before,
    // so it also starts from offset 0 and reads the exact same 3 messages, unaffected by "analytics".
    printVector("notifications poll 1", queue.poll("notifications", 0, 10));

    // A 4th message is published.
    queue.publish(0, "order-delivered");

    // "analytics" only gets the new message, since its own offset was already at 3.
    printVector("analytics poll 2 (only new messages)", queue.poll("analytics", 0, 10));

    // "notifications" also only gets the new message, since its own offset was independently at 3 too.
    printVector("notifications poll 2 (only new messages)", queue.poll("notifications", 0, 10));

    // The log itself still holds all 4 messages, retained regardless of either group's consumption.
    cout << "Partition 0 still retains all published messages: " << queue.partitionSize(0) << endl;

    return 0;
}

